INSERT INTO `course_exam_record` VALUES (11, 28, 14, 30, 30, 3, 3, 1, 20, '[{\"score\": 10, \"content\": \"志愿服务的核心精神是什么？\", \"correct\": true, \"questionId\": 21, \"userAnswer\": \"B\", \"explanation\": \"志愿服务的核心精神是\\\"奉献、友爱、互助、进步\\\"，这是中国志愿服务精神的高度概括。\", \"correctAnswer\": \"B\"}, {\"score\": 10, \"content\": \"在志愿服务中遇到紧急情况应该首先做什么？\", \"correct\": true, \"questionId\": 22, \"userAnswer\": \"C\", \"explanation\": \"遇到紧急情况应该首先保持冷静，评估情况并寻求帮助，确保自身和他人安全。\", \"correctAnswer\": \"C\"}, {\"score\": 10, \"content\": \"以下哪项不属于志愿者的基本权利？\", \"correct\": true, \"questionId\": 23, \"userAnswer\": \"C\", \"explanation\": \"志愿服务是自愿、无偿的，\\\"无条件获得报酬\\\"不属于志愿者的基本权利。\", \"correctAnswer\": \"C\"}]', NULL, '2026-03-04 10:54:20', 0, '2026-03-04 10:54:20', '2026-03-04 10:54:20', 0);
