INSERT INTO `course_question` VALUES (1, 2, 1, '志愿服务精神的精髓是？', '[\"奉献\", \"索取\", \"赢利\", \"强制\"]', 'A', 10, 1, '志愿服务的核心是奉献精神。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (2, 2, 1, '志愿者在服务中享有的基本权利不包括？', '[\"获得必要的培训\", \"获得安全保障\", \"随意更改服务计划\", \"了解服务内容\"]', 'C', 10, 1, '志愿者应服从组织安排，不能随意更改服务计划。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (3, 2, 1, '志愿服务的基本原则之一是？', '[\"强制性\", \"无偿性\", \"营利性\", \"随意性\"]', 'B', 10, 1, '志愿服务具有自愿性和无偿性。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (4, 2, 1, '《志愿服务条例》指出，志愿服务组织应当如实记录志愿者的？', '[\"所有个人隐私\", \"家庭成员信息\", \"志愿服务时间、内容、评价\", \"消费习惯\"]', 'C', 10, 1, '服务时间、内容和评价是志愿服务记录的核心内容。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (5, 2, 1, '当志愿者与受助者之间产生矛盾时，志愿者应该？', '[\"据理力争\", \"保持冷静并及时向组织反馈\", \"私下解决\", \"立即终止服务并离开\"]', 'B', 10, 1, '冷静处理并反馈给组织是专业志愿者的做法。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (6, 2, 1, '在接电话时，第一句话通常应该是？', '[\"喂，找谁\", \"你好，这里是志愿者服务台\", \"有什么事吗\", \"说话\"]', 'B', 10, 1, '礼貌的问候和自报家门是基本的通话礼仪。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (7, 2, 1, '作为志愿者，在服务现场着装应要求？', '[\"时尚前卫\", \"整洁得体，统一佩戴标识\", \"随意搭配\", \"名牌服饰\"]', 'B', 10, 1, '整洁得体并佩戴标识有利于树立志愿者专业形象。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (8, 2, 1, '与受助者沟通时，应注意？', '[\"不停打断对方\", \"使用祈使句命令对方\", \"倾听并保持眼神交流\", \"面无表情\"]', 'C', 10, 1, '倾听和非语言交流（眼神）是沟通的核心。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (9, 1, 1, '进行心肺复苏(CPR)时，胸外按压的深度通常为？', '[\"1-2厘米\", \"3-4厘米\", \"5-6厘米\", \"7-8厘米\"]', 'C', 10, 2, '成人胸外按压深度要求5-6cm。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (10, 1, 1, '心肺复苏时按压与人工呼吸的比例是？', '[\"5:1\", \"15:2\", \"30:2\", \"50:5\"]', 'C', 10, 2, '单人或双人CPR对于成人均为30:2。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (11, 1, 1, '遇到骨折出血的伤员，首先应？', '[\"立即搬运\", \"进行固定和止血\", \"让其剧烈活动\", \"进行按摩\"]', 'B', 10, 2, '先行止血和固定可以防止二次伤害。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (12, 2, 1, '志愿者在服务中感到由于工作压力带来的心理疲劳，应该？', '[\"硬撑到底\", \"自我调节或寻求专业心理支持\", \"随便找受助者倾诉\", \"直接放弃不打招呼\"]', 'B', 10, 2, '心理建设也是志愿者的必修课。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (13, 2, 1, '双向沟通比单向沟通效果更好的原因是？', '[\"速度快\", \"干扰少\", \"有反馈且信息更准确\", \"更省力\"]', 'C', 10, 1, '反馈机制能确保信息被准确理解。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (14, 2, 1, '与视障人士同行时，你应该？', '[\"用力推他走\", \"让他扶住你的胳膊肘部，根据你的步速前行\", \"在他前面大声喊叫引导\", \"让他自己摸索\"]', 'B', 10, 2, '扶肘引导是标准的视障人士助行方式。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (15, 2, 1, '与高龄老人交流时，语速应该？', '[\"越快越好\", \"适中且略慢，确保老人听清\", \"大声吼叫\", \"使用方言俚语\"]', 'B', 10, 1, '适中偏慢的语速符合老人的生理特点。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (16, 2, 3, '判断题：志愿者在服务过程中产生的所有费用均必须由受助者承担。', '[\"正确\", \"错误\"]', 'B', 10, 1, '志愿服务具有无偿性，费用通常由组织方提供或志愿者自理，不得向受助者强制索要。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (17, 2, 3, '判断题：志愿服务记录证明可以作为升学、就业的参考依据。', '[\"正确\", \"错误\"]', 'A', 10, 1, '国家鼓励相关部门和单位在升学就业中参考志愿服务记录。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (18, 2, 1, '世界志愿者日是每年的哪一天？', '[\"3月5日\", \"12月1日\", \"12月5日\", \"10月1日\"]', 'C', 10, 1, '12月5日是国际志愿者日。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (19, 2, 1, '志愿服务组织的法律属性通常是？', '[\"营利性企业\", \"非营利性组织\", \"政府机关\", \"非法组织\"]', 'B', 10, 1, '非营利性是志愿服务组织的核心属性。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (20, 2, 1, '如果服务对象在服务过程中突发疾病，志愿者应该？', '[\"自行买药给对方吃\", \"拍照留证后离开\", \"立即对受助者采取急救措施并拨打120\", \"让对方忍一忍\"]', 'C', 10, 1, '及时救助和呼叫专业救援是标准流程。', 0, 1, '2026-01-20 23:05:14', '2026-03-04 10:48:31', 1);
INSERT INTO `course_question` VALUES (21, 0, 1, '志愿服务的核心精神是什么？', '[\"追求个人利益\", \"奉献、友爱、互助、进步\", \"强制性服务\", \"获得报酬\"]', 'B', 10, 1, '志愿服务的核心精神是\"奉献、友爱、互助、进步\"，这是中国志愿服务精神的高度概括。', 1, 1, '2026-03-04 10:48:31', '2026-03-04 10:48:31', 0);
INSERT INTO `course_question` VALUES (22, 0, 1, '在志愿服务中遇到紧急情况应该首先做什么？', '[\"立即离开现场\", \"先拍照发朋友圈\", \"保持冷静，评估情况并寻求帮助\", \"置之不理\"]', 'C', 10, 1, '遇到紧急情况应该首先保持冷静，评估情况并寻求帮助，确保自身和他人安全。', 2, 1, '2026-03-04 10:48:31', '2026-03-04 10:48:31', 0);
INSERT INTO `course_question` VALUES (23, 0, 1, '以下哪项不属于志愿者的基本权利？', '[\"获得培训的权利\", \"获得必要的安全保障\", \"无条件获得报酬\", \"了解服务内容的权利\"]', 'C', 10, 1, '志愿服务是自愿、无偿的，\"无条件获得报酬\"不属于志愿者的基本权利。', 3, 1, '2026-03-04 10:48:31', '2026-03-04 10:48:31', 0);
