INSERT INTO `volunteer` VALUES (1, 65, '陈波', 0, '2024000010', '计算机学院', '网络工程', '2404班', '2024', 21.00, 896, 100, 1, '[\"环境保护\", \"社区服务\"]', '英语六级,日语N2,商务翻译,跨文化交流', '计算机专业学生，擅长技术支持和网络维护。喜欢参与科技类志愿活动，帮助老人学习使用智能手机。', NULL, NULL, NULL, '2026-01-19 12:11:36', '2026-03-12 21:09:00', 0);
INSERT INTO `volunteer` VALUES (2, 66, '周伟', 0, '2024000110', '经济管理学院', '人力资源', '2402班', '2024', 21.00, 305, 191, 4, '[\"大型赛会\", \"支教助学\"]', '急救技能,健康科普,血压测量,心肺复苏', '医学院学生，热心于健康科普和义诊活动。曾多次参与社区健康讲座，帮助居民了解常见疾病预防知识。', NULL, NULL, NULL, '2026-01-19 12:11:36', '2026-03-12 21:09:00', 0);
INSERT INTO `volunteer` VALUES (3, 67, '陈国', 0, '2024000210', '艺术学院', '艺术设计', '2406班', '2024', 18.00, 636, 259, 3, '[\"支教助学\", \"文化宣传\"]', '钢琴十级,声乐,吉他弹唱,音乐教学', '外语专业，英语和日语流利。经常参与国际交流活动，担任翻译志愿者，帮助外国友人了解中国文化。', NULL, NULL, NULL, '2026-01-19 12:11:36', '2026-03-12 21:09:00', 0);
INSERT INTO `volunteer` VALUES (4, 68, '杨婷', 1, '2024000009', '计算机学院', '数据科学', '2403班', '2024', 21.00, 859, 534, 3, '[\"敬老助残\", \"文化宣传\"]', '素描,水彩画,手工制作,书法', '艺术学院学生，擅长绘画和手工。热衷于为山区儿童开展美术支教活动，用艺术点亮孩子们的梦想。', NULL, NULL, NULL, '2026-01-19 12:11:36', '2026-03-12 21:09:00', 0);
INSERT INTO `volunteer` VALUES (5, 69, '董梦', 1, '2024000109', '经济管理学院', '市场营销', '2401班', '2024', 21.00, 341, 111, 5, '[\"环境保护\", \"社区服务\"]', '篮球,足球,游泳,体育教学', '法学专业学生，关注弱势群体权益保护。参与法律援助志愿服务，为社区居民提供免费法律咨询。', NULL, NULL, NULL, '2026-01-19 12:11:36', '2026-03-12 21:09:00', 0);
INSERT INTO `volunteer` VALUES (6, 70, '张欣', 1, '2024000209', '艺术学院', '舞蹈学', '2405班', '2024', 21.00, 1027, 230, 1, '[\"支教助学\", \"文化宣传\"]', '摄影,视频剪辑,Photoshop,新媒体运营', '教育学院学生，有丰富的家教经验。积极参与留守儿童帮扶项目，陪伴孩子们学习和成长。', NULL, NULL, NULL, '2026-01-19 12:11:36', '2026-03-12 21:09:00', 0);
INSERT INTO `volunteer` VALUES (7, 71, '李涛', 0, '2024000008', '计算机学院', '人工智能', '2402班', '2024', 21.00, 222, 108, 2, '[\"大型赛会\", \"支教助学\"]', '演讲主持,活动策划,团队管理,PPT制作', '音乐专业学生，擅长钢琴和声乐。定期前往养老院开展文艺表演，用音乐温暖老人们的心灵。', NULL, NULL, NULL, '2026-01-19 12:11:36', '2026-03-12 21:09:00', 0);
INSERT INTO `volunteer` VALUES (8, 72, '宋威', 0, '2024000108', '经济管理学院', '金融学', '2406班', '2024', 18.00, 520, 105, 2, '[\"环境保护\", \"社区服务\"]', '心理咨询,情绪疏导,倾听陪伴,危机干预', '体育学院学生，热爱运动。担任社区运动会志愿者，组织青少年体育活动，传播健康生活理念。', NULL, NULL, NULL, '2026-01-19 12:11:36', '2026-03-12 21:09:00', 0);
