-- ----------------------------
-- Table structure for activity_evaluation
-- ----------------------------
DROP TABLE IF EXISTS `activity_evaluation`;
CREATE TABLE `activity_evaluation`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '评价ID',
  `activity_id` bigint NOT NULL COMMENT '活动ID',
  `volunteer_id` bigint NOT NULL COMMENT '志愿者ID',
  `rating` tinyint NOT NULL DEFAULT 5 COMMENT '评分(1-5)',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '评价内容',
  `tags` json NULL COMMENT '评价标签',
  `is_anonymous` tinyint NOT NULL DEFAULT 0 COMMENT '是否匿名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_activity_volunteer`(`activity_id` ASC, `volunteer_id` ASC) USING BTREE,
  INDEX `idx_volunteer`(`volunteer_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '活动评价表' ROW_FORMAT = DYNAMIC;

