-- ----------------------------
-- Table structure for activity_review
-- ----------------------------
DROP TABLE IF EXISTS `activity_review`;
CREATE TABLE `activity_review`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '评价ID',
  `activity_id` bigint NOT NULL COMMENT '关联活动',
  `volunteer_id` bigint NOT NULL COMMENT '评价人',
  `organizer_id` bigint NOT NULL COMMENT '被评价的组织者',
  `score` tinyint NOT NULL COMMENT '评分 (1-5星)',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '评价内容',
  `reply_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '组织者回复内容',
  `reply_time` datetime NULL DEFAULT NULL COMMENT '回复时间',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 (0=正常显示, 1=申诉中/隐藏, 2=已屏蔽)',
  `is_anonymous` tinyint NOT NULL DEFAULT 0 COMMENT '是否匿名 (0-否, 1-是)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_activity`(`activity_id` ASC) USING BTREE,
  INDEX `idx_volunteer`(`volunteer_id` ASC) USING BTREE,
  INDEX `idx_organizer`(`organizer_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '活动服务评价表' ROW_FORMAT = DYNAMIC;

