  `user_id` bigint NOT NULL COMMENT '评论用户ID',
  `target_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标类型：ACTIVITY,EXPERIENCE,COURSE',
