-- ----------------------------
-- Table structure for course
-- ----------------------------
DROP TABLE IF EXISTS `course`;
CREATE TABLE `course`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '课程ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程标题',
  `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '封面图片',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '课程分类',
  `course_type` tinyint NOT NULL DEFAULT 1 COMMENT '课程类型:1-视频,2-图文',
  `instructor` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '讲师/主讲人',
  `summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '课程摘要',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '课程内容',
  `video_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '视频地址',
  `duration` int NOT NULL DEFAULT 0 COMMENT '时长(分钟)',
  `credit_hours` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '学分/学时',
  `points_reward` int NOT NULL DEFAULT 0 COMMENT '完成奖励积分',
  `exam_points` int NOT NULL DEFAULT 0 COMMENT '考试通过奖励积分',
  `has_exam` tinyint NOT NULL DEFAULT 0 COMMENT '是否有考试',
  `difficulty` tinyint NOT NULL DEFAULT 1 COMMENT '难度:1-初级,2-中级,3-高级',
  `is_required` tinyint NOT NULL DEFAULT 0 COMMENT '是否必修',
  `view_count` int NOT NULL DEFAULT 0 COMMENT '观看次数',
  `like_count` int NOT NULL DEFAULT 0 COMMENT '点赞数',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态:0-下架,1-上架',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_category`(`category` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 321 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '培训课程表' ROW_FORMAT = DYNAMIC;

