-- ----------------------------
-- Table structure for course_exam
-- ----------------------------
DROP TABLE IF EXISTS `course_exam`;
CREATE TABLE `course_exam`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '考试ID',
  `course_id` bigint NOT NULL COMMENT '课程ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '考试标题',
  `pass_score` int NOT NULL DEFAULT 60 COMMENT '及格分数',
  `total_score` int NOT NULL DEFAULT 100 COMMENT '总分',
  `time_limit` int NOT NULL DEFAULT 30 COMMENT '考试时长(分钟)',
  `question_count` int NOT NULL DEFAULT 10 COMMENT '题目数量',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态:0-禁用,1-启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_deleted` tinyint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_course`(`course_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 301 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '课程考试表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of course_exam
-- ----------------------------

-- ----------------------------
-- Table structure for course_exam_record
-- ----------------------------
DROP TABLE IF EXISTS `course_exam_record`;
CREATE TABLE `course_exam_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `volunteer_id` bigint NOT NULL COMMENT '志愿者ID',
  `course_id` bigint NOT NULL COMMENT '课程ID',
  `score` int NOT NULL DEFAULT 0 COMMENT '得分',
  `total_score` int NOT NULL DEFAULT 100 COMMENT '总分',
  `correct_count` int NOT NULL DEFAULT 0 COMMENT '正确题数',
  `total_count` int NOT NULL DEFAULT 0 COMMENT '总题数',
  `passed` tinyint NOT NULL DEFAULT 0 COMMENT '是否通过:0-否,1-是',
  `points_reward` int NOT NULL DEFAULT 0 COMMENT '获得积分',
  `answers` json NULL COMMENT '答题详情(JSON)',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `submit_time` datetime NULL DEFAULT NULL COMMENT '提交时间',
  `time_spent` int NULL DEFAULT NULL COMMENT '用时(秒)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_volunteer`(`volunteer_id` ASC) USING BTREE,
  INDEX `idx_course`(`course_id` ASC) USING BTREE,
  INDEX `idx_passed`(`passed` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '课程考试记录表' ROW_FORMAT = DYNAMIC;

