-- ----------------------------
-- Table structure for course_progress
-- ----------------------------
DROP TABLE IF EXISTS `course_progress`;
CREATE TABLE `course_progress`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `volunteer_id` bigint NOT NULL COMMENT '志愿者ID',
  `course_id` bigint NOT NULL COMMENT '课程ID',
  `progress` int NULL DEFAULT 0 COMMENT '学习进度(0-100%)',
  `study_duration` int NULL DEFAULT 0 COMMENT '已学习时长(秒)',
  `total_duration` int NULL DEFAULT 0 COMMENT '课程总时长(秒)',
  `last_position` int NULL DEFAULT 0 COMMENT '最后学习位置(秒)',
  `last_study_time` datetime NULL DEFAULT NULL COMMENT '最后学习时间',
  `is_completed` tinyint NULL DEFAULT 0 COMMENT '是否已完成学习',
  `completed_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_volunteer_course`(`volunteer_id` ASC, `course_id` ASC) USING BTREE,
  INDEX `idx_volunteer_id`(`volunteer_id` ASC) USING BTREE,
  INDEX `idx_course_id`(`course_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '课程学习进度表' ROW_FORMAT = DYNAMIC;

