  `prize_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '奖品名称',
  `prize_type` tinyint NULL DEFAULT NULL COMMENT '奖品类型',
  `prize_value` int NULL DEFAULT NULL COMMENT '奖品价值',
  `points_cost` int NOT NULL DEFAULT 0 COMMENT '消耗积分',
  `is_won` tinyint NOT NULL DEFAULT 0 COMMENT '是否中奖',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-待领取，1-已领取，2-已过期',
