-- ----------------------------
-- Procedure structure for mock_data_generator_v7
-- ----------------------------
DROP PROCEDURE IF EXISTS `mock_data_generator_v7`;
delimiter ;;
CREATE PROCEDURE `mock_data_generator_v7`()
BEGIN
    -- 基础变量
    DECLARE v_i INT DEFAULT 0;
    DECLARE o_i INT DEFAULT 0;
    DECLARE a_i INT DEFAULT 0; -- 活动计数器 0-299
    DECLARE user_id BIGINT;
    DECLARE default_pass VARCHAR(255) DEFAULT '$2a$10$N.zmdr9k7uOCQb376NoUnuTJ8iAt6Z5EHsM8lE9lBOsl7iKTVKIUi';
    
    -- 活动生成变量
    DECLARE current_cat_id INT;
    DECLARE current_org_id BIGINT;
    DECLARE base_title VARCHAR(100);
    DECLARE sub_title VARCHAR(50);
    DECLARE v_keyword VARCHAR(50);
    DECLARE v_final_title VARCHAR(255);
    DECLARE v_content TEXT;
    
    -- ---------------------------------------------------
    -- 1. 生成志愿者 (45人)
    -- ---------------------------------------------------
    SET v_i = 0;
    WHILE v_i < 45 DO
        VALUES (CAST((2024001001 + v_i) AS CHAR), default_pass, 'VOLUNTEER', 1, CONCAT('https://api.dicebear.com/7.x/avataaars/svg?seed=stu_', v_i), 'stu@test.com', CONCAT('同学', v_i));
        SET user_id = LAST_INSERT_ID();
        VALUES (user_id, CONCAT('学生', v_i), 1, CAST((2024001001 + v_i) AS CHAR), '计算机学院', '软件工程', '1班', 0, 0);
        SET v_i = v_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 2. 生成 12 个组织 (对应不同分类)
    -- ---------------------------------------------------
    -- 插入顺序影响ID，假设ID为 2-13 (admin占了1)
    
    -- 填充 organizer 表 (简化，直接对应sys_user)
    SELECT id, nickname, '负责人', 1 FROM sys_user WHERE role = 'ORGANIZER';

    -- ---------------------------------------------------
    -- 3. 生成 300 个活动 (绝对不重复逻辑)
    -- ---------------------------------------------------
    SET a_i = 0;
    WHILE a_i < 300 DO
        -- 轮询分类 1-7
        SET current_cat_id = (a_i % 7) + 1;
        
        -- 根据分类选择具体的活动标题和组织者
        -- 使用取模运算 (a_i % 15) 确保循环使用不同的文案
        
        CASE current_cat_id
            WHEN 1 THEN -- 社区服务 (对应 后勤、校青协、法学院)
                SET current_org_id = ELT((a_i % 3) + 1, 10, 3, 11); 
                SET v_keyword = 'community';
                SET base_title = CASE (a_i % 12)
                    WHEN 0 THEN '老旧小区楼道清理行动'
                    WHEN 1 THEN '社区垃圾分类定点指导'
                    WHEN 2 THEN '居民法律知识普及宣讲'
                    WHEN 3 THEN '社区独居老人水电检修'
                    WHEN 4 THEN '流浪猫狗绝育与安置协助'
                    WHEN 5 THEN '社区出入口交通文明劝导'
                    WHEN 6 THEN '邻里互助跳蚤市场秩序维护'
                    WHEN 7 THEN '防电信诈骗社区扫楼宣传'
                    WHEN 8 THEN '社区公共健身器材维护'
                    WHEN 9 THEN '暑期儿童托管中心协助'
                    WHEN 10 THEN '社区卫生死角大扫除'
                    ELSE '爱心义剪进社区服务'
                END;
                
            WHEN 2 THEN -- 环境保护 (对应 环境学院、校青协)
                SET current_org_id = ELT((a_i % 2) + 1, 5, 3);
                SET v_keyword = 'nature';
                SET base_title = CASE (a_i % 10)
                    WHEN 0 THEN '校园人工湖水质监测'
                    WHEN 1 THEN '周边公园外来物种清理'
                    WHEN 2 THEN '“限塑令”超市门口宣传'
                    WHEN 3 THEN '废旧电池定点回收计划'
                    WHEN 4 THEN '植树节校园绿化养护'
                    WHEN 5 THEN '河流沿岸垃圾捡拾行动'
                    WHEN 6 THEN '生物多样性调研助手'
                    WHEN 7 THEN '光盘行动食堂引导'
                    WHEN 8 THEN '旧衣物循环利用分拣'
                    ELSE '环保酵素制作推广'
                END;

            WHEN 3 THEN -- 支教助学 (对应 外语学院、校青协)
                SET current_org_id = ELT((a_i % 2) + 1, 4, 3);
                SET v_keyword = 'teaching';
                SET base_title = CASE (a_i % 10)
                    WHEN 0 THEN '阳光小学课后作业辅导'
                    WHEN 1 THEN '乡村儿童英语启蒙夏令营'
                    WHEN 2 THEN '特殊教育学校周末陪伴'
                    WHEN 3 THEN '流动儿童城市融入计划'
                    WHEN 4 THEN '爱心图书室整理与捐赠'
                    WHEN 5 THEN '趣味科学实验进小学'
                    WHEN 6 THEN '“云支教”线上伴读'
                    WHEN 7 THEN '少数民族学生普通话推广'
                    WHEN 8 THEN '留守儿童书信交流项目'
                    ELSE '高考志愿填报公益咨询'
                END;

            WHEN 4 THEN -- 科技服务 (对应 计算机、机械)
                SET current_org_id = ELT((a_i % 2) + 1, 2, 12);
                SET v_keyword = 'technology';
                SET base_title = CASE (a_i % 10)
                    WHEN 0 THEN '社区电脑义务维修诊所'
                    WHEN 1 THEN '老年人智能手机操作培训'
                    WHEN 2 THEN '校园网络故障排查小分队'
                    WHEN 3 THEN '3D打印技术科普体验展'
                    WHEN 4 THEN '无人机飞行演示与教学'
                    WHEN 5 THEN '办公软件Office技能培训'
                    WHEN 6 THEN '家庭电器简易故障排查'
                    WHEN 7 THEN '网络安全周技术支持'
                    WHEN 8 THEN 'Python编程少儿入门'
                    ELSE '实验室仪器设备维护'
                END;

            WHEN 5 THEN -- 赛会服务 (对应 体育部、校青协)
                SET current_org_id = ELT((a_i % 2) + 1, 7, 3);
                SET v_keyword = 'sports';
                SET base_title = CASE (a_i % 10)
                    WHEN 0 THEN '城市马拉松物资补给服务'
                    WHEN 1 THEN '大学生篮球联赛现场引导'
                    WHEN 2 THEN '校运动会裁判助理'
                    WHEN 3 THEN '游泳馆救生员助理'
                    WHEN 4 THEN '足球赛场边捡球服务'
                    WHEN 5 THEN '体育器材室整理与借还'
                    WHEN 6 THEN '晨跑打卡监督志愿者'
                    WHEN 7 THEN '残运会无障碍协助'
                    WHEN 8 THEN '电子竞技大赛现场统筹'
                    ELSE '广场舞大赛秩序维护'
                END;

            WHEN 6 THEN -- 敬老关怀 (对应 红十字、校医院)
                SET current_org_id = ELT((a_i % 2) + 1, 6, 13);
                SET v_keyword = 'elderly';
                SET base_title = CASE (a_i % 10)
                    WHEN 0 THEN '夕阳红敬老院包饺子'
                    WHEN 1 THEN '独居老人“陪聊”计划'
                    WHEN 2 THEN '老年人免费体检引导'
                    WHEN 3 THEN '为老人读报与教用微信'
                    WHEN 4 THEN '阿尔茨海默症黄手环发放'
                    WHEN 5 THEN '重阳节文艺汇演筹备'
                    WHEN 6 THEN '老人回忆录口述记录'
                    WHEN 7 THEN '协助老人购买生活物资'
                    WHEN 8 THEN '社区测量血压公益岗'
                    ELSE '敬老院卫生大扫除'
                END;

            ELSE -- 文化艺术 (对应 艺术学院、图书馆)
                SET current_org_id = ELT((a_i % 2) + 1, 8, 9);
                SET v_keyword = 'art';
                SET base_title = CASE (a_i % 10)
                    WHEN 0 THEN '图书馆新书上架与整理'
                    WHEN 1 THEN '校史馆志愿讲解员招募'
                    WHEN 2 THEN '校园井盖创意涂鸦美化'
                    WHEN 3 THEN '非遗剪纸文化体验助教'
                    WHEN 4 THEN '博物馆周末引导员'
                    WHEN 5 THEN '合唱团排练后勤保障'
                    WHEN 6 THEN '毕业生设计展布展协助'
                    WHEN 7 THEN '校园广播台文稿编辑'
                    WHEN 8 THEN '古籍修复基础体验协助'
                    ELSE '迎新晚会舞台搭建协助'
                END;
        END CASE;

        -- 生成后缀，进一步区分 (例如：第1期、第2期...)
        SET sub_title = CONCAT('(第', FLOOR(a_i / 7) + 1, '期)');
        
        SET v_final_title = CONCAT(base_title, ' ', sub_title);

        -- 插入数据
            `title`, `category_id`, `organizer_id`, `cover_image`, `content`, `location`, 
            `start_time`, `end_time`, `deadline`, 
            `max_participants`, `current_participants`, `status`, `audit_status`, `service_hours`
        ) VALUES (
            v_final_title, 
            current_cat_id, 
            (SELECT id FROM organizer WHERE user_id = current_org_id LIMIT 1), 
            CONCAT('https://loremflickr.com/800/450/', v_keyword, '?lock=', a_i), 
            CONCAT('<p>【', base_title, '】正式招募！</p><p>这是校园志愿者系统生成的真实模拟数据。</p><p><b>活动内容：</b>', base_title, '需要同学们的积极参与。</p>'), 
            ELT(FLOOR(1+RAND()*4), '第一教学楼', '学生活动中心', '校外社区', '图书馆广场'),
            DATE_ADD(NOW(), INTERVAL FLOOR(RAND()*60)-30 DAY),
            DATE_ADD(NOW(), INTERVAL FLOOR(RAND()*60)-29 DAY),
            DATE_ADD(NOW(), INTERVAL FLOOR(RAND()*60)-31 DAY),
            50, 0, FLOOR(2+RAND()*3), 1, 2
        );
        SET a_i = a_i + 1;
    END WHILE;
END
;;
delimiter ;

