-- ----------------------------
-- Procedure structure for mock_data_generator_v9
-- ----------------------------
DROP PROCEDURE IF EXISTS `mock_data_generator_v9`;
delimiter ;;
CREATE PROCEDURE `mock_data_generator_v9`()
BEGIN
    DECLARE v_i INT DEFAULT 0;
    DECLARE o_i INT DEFAULT 0;
    DECLARE a_i INT DEFAULT 0;
    DECLARE r_i INT DEFAULT 0;
    DECLARE user_id BIGINT;
    DECLARE default_pass VARCHAR(255) DEFAULT '$2a$10$N.zmdr9k7uOCQb376NoUnuTJ8iAt6Z5EHsM8lE9lBOsl7iKTVKIUi';
    
    DECLARE current_stu_no VARCHAR(20);
    DECLARE v_college VARCHAR(50);
    
    -- 活动变量
    DECLARE current_cat_id INT;
    DECLARE current_org_id BIGINT;
    DECLARE base_title VARCHAR(100);
    DECLARE v_keyword VARCHAR(50);
    DECLARE v_final_title VARCHAR(255);
    DECLARE v_final_content TEXT;
    
    -- 文案模板
    DECLARE txt_bg VARCHAR(255);
    DECLARE txt_duty VARCHAR(255);
    DECLARE txt_req VARCHAR(255);
    
    -- ---------------------------------------------------
    -- 1. 生成志愿者 (270人 = 9学院 * 30人)
    -- ---------------------------------------------------
    SET v_i = 0;
    WHILE v_i < 270 DO
        SET current_stu_no = CAST((2024001001 + v_i) AS CHAR);
        
        -- 计算学院 (每30人换一个学院)
        SET v_college = CASE FLOOR(v_i / 30) 
            WHEN 0 THEN '计算机学院' WHEN 1 THEN '软件学院' WHEN 2 THEN '外国语学院' 
            WHEN 3 THEN '经济管理学院' WHEN 4 THEN '艺术设计学院' WHEN 5 THEN '土木工程学院' 
            WHEN 6 THEN '电气工程学院' WHEN 7 THEN '机械工程学院' ELSE '其他学院' END;

        VALUES (current_stu_no, default_pass, 'VOLUNTEER', 1, CONCAT('https://api.dicebear.com/7.x/avataaars/svg?seed=stu_', v_i), CONCAT('stu', v_i, '@test.com'), CONCAT('同学', v_i), CONCAT('138', LPAD(FLOOR(RAND()*100000000), 8, '0')));
        SET user_id = LAST_INSERT_ID();
        
        -- 生成随机时长 (5-100小时) 和 积分 (20-500分)，拒绝0数据
        VALUES (
            user_id, 
            CONCAT(SUBSTRING(v_college, 1, 2), '同学', (v_i % 30 + 1)), -- 姓名如：计算同学1
            (v_i % 2 + 1), 
            current_stu_no, 
            v_college, 
            '模拟专业', 
            CONCAT('24级', FLOOR(1+RAND()*5), '班'), 
            FLOOR(5 + RAND() * 95), -- 随机时长 5-100
            FLOOR(20 + RAND() * 480) -- 随机积分 20-500
        );
        SET v_i = v_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 2. 生成 12 个组织
    -- ---------------------------------------------------
    
    SELECT id, nickname, '负责人', 1 FROM sys_user WHERE role = 'ORGANIZER';

    -- ---------------------------------------------------
    -- 3. 生成 300 个活动 (V8版文案)
    -- ---------------------------------------------------
    SET a_i = 0;
    WHILE a_i < 300 DO
        SET current_cat_id = (a_i % 7) + 1;
        
        CASE current_cat_id
            WHEN 1 THEN -- 社区服务
                SET current_org_id = ELT((a_i % 3) + 1, 10, 3, 11); 
                SET v_keyword = 'community,volunteer';
                SET base_title = CASE (a_i % 12) WHEN 0 THEN '老旧小区楼道清理行动' WHEN 1 THEN '社区垃圾分类定点指导' WHEN 2 THEN '居民法律知识普及宣讲' WHEN 3 THEN '社区独居老人水电检修' WHEN 4 THEN '流浪猫狗绝育与安置协助' WHEN 5 THEN '社区出入口交通文明劝导' WHEN 6 THEN '邻里互助跳蚤市场秩序维护' WHEN 7 THEN '防电信诈骗社区扫楼宣传' WHEN 8 THEN '社区公共健身器材维护' WHEN 9 THEN '暑期儿童托管中心协助' WHEN 10 THEN '社区卫生死角大扫除' ELSE '爱心义剪进社区服务' END;
                SET txt_bg = '为建设和谐美丽社区，弘扬“奉献、友爱、互助、进步”的志愿精神，我们联合街道办发起本次社区服务活动。';
                SET txt_duty = '1. 协助社区工作人员进行现场布置；<br>2. 负责相关区域的卫生清洁与秩序维护；<br>3. 耐心解答居民咨询，发放宣传手册。';
            WHEN 2 THEN -- 环境保护
                SET current_org_id = ELT((a_i % 2) + 1, 5, 3);
                SET v_keyword = 'nature,cleaning';
                SET base_title = CASE (a_i % 10) WHEN 0 THEN '校园人工湖水质监测' WHEN 1 THEN '周边公园外来物种清理' WHEN 2 THEN '“限塑令”超市门口宣传' WHEN 3 THEN '废旧电池定点回收计划' WHEN 4 THEN '植树节校园绿化养护' WHEN 5 THEN '河流沿岸垃圾捡拾行动' WHEN 6 THEN '生物多样性调研助手' WHEN 7 THEN '光盘行动食堂引导' WHEN 8 THEN '旧衣物循环利用分拣' ELSE '环保酵素制作推广' END;
                SET txt_bg = '绿水青山就是金山银山。为了提升大家的环保意识，改善我们的校园及周边生态环境，特举办此次环保公益行动。';
                SET txt_duty = '1. 开展定点清理与环境监测工作；<br>2. 向路人普及环保知识，引导垃圾分类；<br>3. 拍摄活动照片，记录环境改善过程。';
            WHEN 3 THEN -- 支教助学
                SET current_org_id = ELT((a_i % 2) + 1, 4, 3);
                SET v_keyword = 'teaching,kids';
                SET base_title = CASE (a_i % 10) WHEN 0 THEN '阳光小学课后作业辅导' WHEN 1 THEN '乡村儿童英语启蒙夏令营' WHEN 2 THEN '特殊教育学校周末陪伴' WHEN 3 THEN '流动儿童城市融入计划' WHEN 4 THEN '爱心图书室整理与捐赠' WHEN 5 THEN '趣味科学实验进小学' WHEN 6 THEN '“云支教”线上伴读' WHEN 7 THEN '少数民族学生普通话推广' WHEN 8 THEN '留守儿童书信交流项目' ELSE '高考志愿填报公益咨询' END;
                SET txt_bg = '教育是点亮未来的光。我们希望通过大学生的知识和陪伴，为需要帮助的孩子们带去温暖和希望。';
                SET txt_duty = '1. 辅导中小学生完成课后作业；<br>2. 组织趣味英语、科学小实验等互动课程；<br>3. 关注孩子心理健康，提供陪伴与倾听。';
            WHEN 4 THEN -- 科技服务
                SET current_org_id = ELT((a_i % 2) + 1, 2, 12);
                SET v_keyword = 'computer,tech';
                SET base_title = CASE (a_i % 10) WHEN 0 THEN '社区电脑义务维修诊所' WHEN 1 THEN '老年人智能手机操作培训' WHEN 2 THEN '校园网络故障排查小分队' WHEN 3 THEN '3D打印技术科普体验展' WHEN 4 THEN '无人机飞行演示与教学' WHEN 5 THEN '办公软件Office技能培训' WHEN 6 THEN '家庭电器简易故障排查' WHEN 7 THEN '网络安全周技术支持' WHEN 8 THEN 'Python编程少儿入门' ELSE '实验室仪器设备维护' END;
                SET txt_bg = '发挥理工科专业优势，用技术服务社会。本次活动旨在解决大家生活中的电子产品使用难题，普及科技知识。';
                SET txt_duty = '1. 为师生和居民提供电脑清灰、系统重装等服务；<br>2. 手把手教老年人使用微信、挂号等手机功能；<br>3. 讲解网络安全防诈骗知识。';
            WHEN 5 THEN -- 赛会服务
                SET current_org_id = ELT((a_i % 2) + 1, 7, 3);
                SET v_keyword = 'sports,marathon';
                SET base_title = CASE (a_i % 10) WHEN 0 THEN '城市马拉松物资补给服务' WHEN 1 THEN '大学生篮球联赛现场引导' WHEN 2 THEN '校运动会裁判助理' WHEN 3 THEN '游泳馆救生员助理' WHEN 4 THEN '足球赛场边捡球服务' WHEN 5 THEN '体育器材室整理与借还' WHEN 6 THEN '晨跑打卡监督志愿者' WHEN 7 THEN '残运会无障碍协助' WHEN 8 THEN '电子竞技大赛现场统筹' ELSE '广场舞大赛秩序维护' END;
                SET txt_bg = '大型赛事的成功离不开志愿者的辛勤付出。加入我们，感受竞技体育的魅力，展现当代大学生的风采。';
                SET txt_duty = '1. 负责赛场出入口的检票与引导工作；<br>2. 协助裁判记录成绩，维护赛场秩序；<br>3. 为运动员提供补给水和医疗指引。';
            WHEN 6 THEN -- 敬老关怀
                SET current_org_id = ELT((a_i % 2) + 1, 6, 13);
                SET v_keyword = 'elderly,nursing';
                SET base_title = CASE (a_i % 10) WHEN 0 THEN '夕阳红敬老院包饺子' WHEN 1 THEN '独居老人“陪聊”计划' WHEN 2 THEN '老年人免费体检引导' WHEN 3 THEN '为老人读报与教用微信' WHEN 4 THEN '阿尔茨海默症黄手环发放' WHEN 5 THEN '重阳节文艺汇演筹备' WHEN 6 THEN '老人回忆录口述记录' WHEN 7 THEN '协助老人购买生活物资' WHEN 8 THEN '社区测量血压公益岗' ELSE '敬老院卫生大扫除' END;
                SET txt_bg = '老吾老以及人之老。让我们走进敬老院和独居老人家中，用耐心和爱心为他们的晚年生活增添一抹亮色。';
                SET txt_duty = '1. 陪老人聊天解闷，倾听他们的故事；<br>2. 协助老人打扫卫生，整理房间；<br>3. 为老人表演文艺节目，教他们简单的健康操。';
            ELSE -- 文化艺术
                SET current_org_id = ELT((a_i % 2) + 1, 8, 9);
                SET v_keyword = 'art,library';
                SET base_title = CASE (a_i % 10) WHEN 0 THEN '图书馆新书上架与整理' WHEN 1 THEN '校史馆志愿讲解员招募' WHEN 2 THEN '校园井盖创意涂鸦美化' WHEN 3 THEN '非遗剪纸文化体验助教' WHEN 4 THEN '博物馆周末引导员' WHEN 5 THEN '合唱团排练后勤保障' WHEN 6 THEN '毕业生设计展布展协助' WHEN 7 THEN '校园广播台文稿编辑' WHEN 8 THEN '古籍修复基础体验协助' ELSE '迎新晚会舞台搭建协助' END;
                SET txt_bg = '文化需要传承，艺术需要分享。本次活动旨在丰富校园文化生活，提升大家的艺术修养。';
                SET txt_duty = '1. 协助整理书籍、展品，维持场馆安静与整洁；<br>2. 为参观者提供专业的讲解引导服务；<br>3. 参与场地布置与宣传物料制作。';
        END CASE;

        SET txt_req = '1. 身体健康，无不良嗜好；<br>2. 具有良好的沟通能力和团队合作精神；<br>3. 能够按时参加培训及志愿服务活动，不迟到早退。';
        SET v_final_title = CONCAT(base_title, ' (第', FLOOR(a_i / 7) + 1, '期)');
        
        -- 生成500字+的文案
        SET v_final_content = CONCAT(
            '<h4>一、活动背景</h4><p>', txt_bg, '</p>',
            '<h4>二、岗位职责</h4><p>', txt_duty, '</p>',
            '<h4>三、岗位要求</h4><p>', txt_req, '</p>',
            '<h4>四、你将获得</h4><p>1. 志愿时长认证：', FLOOR(2+RAND()*4), '小时；<br>2. 积分奖励：', FLOOR(5+RAND()*10), '积分（可用于积分商城兑换）；<br>3. 结识志同道合的朋友，提升个人能力。</p>',
            '<h4>五、注意事项</h4><p>请报名成功的同学保持电话畅通，负责人将在活动开始前建立微信群。如有疑问请联系主办方。</p>'
        );

            `title`, `category_id`, `organizer_id`, `cover_image`, `content`, `location`, 
            `start_time`, `end_time`, `deadline`, 
            `max_participants`, `current_participants`, `status`, `audit_status`, `service_hours`, `points`
        ) VALUES (
            v_final_title, 
            current_cat_id, 
            (SELECT id FROM organizer WHERE user_id = current_org_id LIMIT 1), 
            CONCAT('https://loremflickr.com/800/450/', v_keyword, '?lock=', a_i), 
            v_final_content, 
            ELT(FLOOR(1+RAND()*4), '第一教学楼', '学生活动中心', '校外社区', '图书馆广场'),
            DATE_ADD(NOW(), INTERVAL FLOOR(RAND()*60)-30 DAY),
            DATE_ADD(NOW(), INTERVAL FLOOR(RAND()*60)-29 DAY),
            DATE_ADD(NOW(), INTERVAL FLOOR(RAND()*60)-31 DAY),
            50, 0, FLOOR(2+RAND()*3), 1, FLOOR(2+RAND()*4), FLOOR(5+RAND()*15)
        );
        SET a_i = a_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 4. 随机生成 1500 条报名记录 (让“我的活动”不为空)
    -- ---------------------------------------------------
    SET r_i = 0;
    WHILE r_i < 1500 DO
        -- 随机选一个活动
        SET @act_id := (SELECT id FROM activity ORDER BY RAND() LIMIT 1);
        -- 随机选一个志愿者
        SET @vol_id := (SELECT id FROM volunteer ORDER BY RAND() LIMIT 1);
        
        -- 插入报名记录 (避免重复主键冲突，使用IGNORE)
        VALUES (
            @act_id, 
            @vol_id, 
            FLOOR(1 + RAND() * 3), -- 1:已报名, 2:已拒绝, 3:已完成
            DATE_ADD(NOW(), INTERVAL -FLOOR(RAND()*30) DAY)
        );
        
        -- 更新活动当前人数
        UPDATE activity SET current_participants = current_participants + 1 WHERE id = @act_id;
        
        SET r_i = r_i + 1;
    END WHILE;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for mock_data_v13
-- ----------------------------
DROP PROCEDURE IF EXISTS `mock_data_v13`;
delimiter ;;
CREATE PROCEDURE `mock_data_v13`()
BEGIN
    DECLARE v_i INT DEFAULT 0;
    DECLARE o_i INT DEFAULT 0;
    DECLARE a_i INT DEFAULT 0;
    DECLARE p_i INT DEFAULT 0; -- 商品计数
    DECLARE c_i INT DEFAULT 0; -- 课程计数
    DECLARE e_i INT DEFAULT 0; -- 心得计数
    
    DECLARE user_id BIGINT;
    DECLARE default_pass VARCHAR(255) DEFAULT '$2a$10$N.zmdr9k7uOCQb376NoUnuTJ8iAt6Z5EHsM8lE9lBOsl7iKTVKIUi';
    
    -- 姓名库
    DECLARE surname VARCHAR(10);
    DECLARE givenname VARCHAR(10);
    DECLARE full_name VARCHAR(20);
    
    -- 活动变量
    DECLARE current_cat_id INT;
    DECLARE current_org_id BIGINT;
    DECLARE v_keyword VARCHAR(50);
    DECLARE base_title VARCHAR(100);
    DECLARE v_final_content TEXT;
    
    -- ---------------------------------------------------
    -- 1. 生成 12 个组织 (挂载到学院)
    -- ---------------------------------------------------
    WHILE o_i < 12 DO
        SET full_name = CASE o_i
            WHEN 0 THEN '计算机学院团委' WHEN 1 THEN '外国语学院青协' WHEN 2 THEN '经济管理学院'
            WHEN 3 THEN '土木工程学院' WHEN 4 THEN '艺术设计学院' WHEN 5 THEN '机械工程学院'
            WHEN 6 THEN '校青年志愿者协会' WHEN 7 THEN '校红十字会' WHEN 8 THEN '图书馆管理委员会'
            WHEN 9 THEN '后勤保障部' WHEN 10 THEN '法学院志愿队' ELSE '体育部'
        END;
        
        VALUES (CONCAT('ORG', LPAD(o_i, 3, '0')), default_pass, 'ORGANIZER', 1, CONCAT('https://api.dicebear.com/7.x/identicon/svg?seed=org_', o_i), full_name, '010-88661234');
        
        SET o_i = o_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 2. 生成 270 个志愿者 (真实姓名)
    -- ---------------------------------------------------
    SET v_i = 0;
    WHILE v_i < 270 DO
        -- 随机生成真实姓名
        SET surname = ELT(FLOOR(1+RAND()*20), '赵','钱','孙','李','周','吴','郑','王','冯','陈','褚','卫','蒋','沈','韩','杨','朱','秦','尤','许');
        SET givenname = ELT(FLOOR(1+RAND()*20), '伟','芳','娜','敏','静','强','磊','洋','艳','杰','娟','涛','明','超','秀','刚','平','燕','辉','玲');
        SET full_name = CONCAT(surname, givenname);
        
        VALUES (CAST((2024001001 + v_i) AS CHAR), default_pass, 'VOLUNTEER', 1, CONCAT('https://api.dicebear.com/7.x/notionists/svg?seed=stu_', v_i), full_name, CONCAT('138', LPAD(FLOOR(RAND()*100000000), 8, '0')));
        
        VALUES (LAST_INSERT_ID(), full_name, (v_i % 2 + 1), CAST((2024001001 + v_i) AS CHAR), 
            ELT(FLOOR(1+RAND()*6), '计算机学院','外国语学院','经管学院','土木学院','艺术学院','机械学院'), 
            '模拟专业', '2401班', FLOOR(RAND()*100), FLOOR(RAND()*500));
        SET v_i = v_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 3. 生成 300 个真实活动 (恢复 V9 逻辑)
    -- ---------------------------------------------------
    WHILE a_i < 300 DO
        SET current_cat_id = (a_i % 7) + 1;
        
        CASE current_cat_id
            WHEN 1 THEN -- 社区服务
                SET v_keyword = 'community';
                SET base_title = ELT(FLOOR(1+RAND()*8), '老旧小区楼道清理', '社区垃圾分类指导', '居民法律知识宣讲', '流浪动物安置协助', '社区交通文明劝导', '防诈骗扫楼宣传', '社区健身器材维护', '爱心义剪进社区');
                SET current_org_id = (SELECT user_id FROM organizer WHERE org_name LIKE '%计算机%' OR org_name LIKE '%法学%' LIMIT 1);
            WHEN 2 THEN -- 环境保护
                SET v_keyword = 'nature';
                SET base_title = ELT(FLOOR(1+RAND()*6), '校园人工湖水质监测', '公园外来物种清理', '“限塑令”宣传行动', '废旧电池回收计划', '河流沿岸垃圾捡拾', '植树节绿化养护');
                SET current_org_id = (SELECT user_id FROM organizer WHERE org_name LIKE '%环境%' OR org_name LIKE '%青协%' LIMIT 1);
            WHEN 3 THEN -- 支教助学
                SET v_keyword = 'teaching';
                SET base_title = ELT(FLOOR(1+RAND()*6), '阳光小学课后辅导', '乡村英语启蒙夏令营', '特殊教育学校陪伴', '流动儿童融入计划', '爱心图书室整理', '趣味科学实验进小学');
                SET current_org_id = (SELECT user_id FROM organizer WHERE org_name LIKE '%外国语%' OR org_name LIKE '%支教%' LIMIT 1);
            WHEN 4 THEN -- 科技服务
                SET v_keyword = 'computer';
                SET base_title = ELT(FLOOR(1+RAND()*6), '电脑义务维修诊所', '老年人智能手机培训', '校园网络故障排查', '3D打印科普体验', '无人机飞行演示', '办公软件Office培训');
                SET current_org_id = (SELECT user_id FROM organizer WHERE org_name LIKE '%计算机%' OR org_name LIKE '%机械%' LIMIT 1);
            WHEN 5 THEN -- 赛会服务
                SET v_keyword = 'sports';
                SET base_title = ELT(FLOOR(1+RAND()*6), '城市马拉松物资补给', '篮球联赛现场引导', '校运动会裁判助理', '游泳馆救生员助理', '电子竞技大赛统筹', '残运会无障碍协助');
                SET current_org_id = (SELECT user_id FROM organizer WHERE org_name LIKE '%体育%' OR org_name LIKE '%青协%' LIMIT 1);
            WHEN 6 THEN -- 敬老关怀
                SET v_keyword = 'elderly';
                SET base_title = ELT(FLOOR(1+RAND()*6), '敬老院包饺子活动', '独居老人陪聊计划', '老年人免费体检引导', '为老人读报教微信', '阿尔茨海默症关爱', '重阳节文艺汇演');
                SET current_org_id = (SELECT user_id FROM organizer WHERE org_name LIKE '%红十字%' OR org_name LIKE '%青协%' LIMIT 1);
            ELSE -- 文化艺术
                SET v_keyword = 'art';
                SET base_title = ELT(FLOOR(1+RAND()*6), '图书馆新书上架', '校史馆讲解员招募', '校园井盖涂鸦美化', '非遗剪纸体验助教', '博物馆周末引导员', '迎新晚会舞台搭建');
                SET current_org_id = (SELECT user_id FROM organizer WHERE org_name LIKE '%艺术%' OR org_name LIKE '%图书馆%' LIMIT 1);
        END CASE;
        
        -- 防止 current_org_id 为空
        IF current_org_id IS NULL THEN SET current_org_id = (SELECT user_id FROM organizer LIMIT 1); END IF;

            `title`, `category_id`, `organizer_id`, `cover_image`, `content`, `location`, 
            `start_time`, `end_time`, `deadline`, 
            `max_participants`, `current_participants`, `status`, `audit_status`, `service_hours`, `points`
        ) VALUES (
            CONCAT(base_title, ' (第', FLOOR(a_i/10)+1, '期)'), 
            current_cat_id, 
            (SELECT id FROM organizer WHERE user_id = current_org_id), 
            CONCAT('https://loremflickr.com/800/450/', v_keyword, '?lock=', a_i), 
            CONCAT('<p><b>活动背景：</b>', base_title, '旨在服务同学，回馈社会。</p><p><b>岗位职责：</b><br>1. 协助现场布置；<br>2. 维持秩序；<br>3. 提供咨询服务。</p><p><b>福利保障：</b><br>1. 志愿时长录入；<br>2. 综测加分；<br>3. 提供饮用水和午餐。</p>'), 
            ELT(FLOOR(1+RAND()*4), '第一教学楼', '学生活动中心', '校外社区', '图书馆广场'),
            DATE_ADD(NOW(), INTERVAL FLOOR(RAND()*60)-30 DAY),
            DATE_ADD(NOW(), INTERVAL FLOOR(RAND()*60)-29 DAY),
            DATE_ADD(NOW(), INTERVAL FLOOR(RAND()*60)-31 DAY),
            50, FLOOR(RAND()*50), FLOOR(2+RAND()*3), 1, FLOOR(2+RAND()*4), FLOOR(5+RAND()*15)
        );
        SET a_i = a_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 4. 生成 200 个商城商品 (含虚拟卡、实物)
    -- ---------------------------------------------------
    WHILE p_i < 200 DO
        VALUES (
            ELT(FLOOR(1+RAND()*10), '活动免审核卡', '双倍积分卡', '补签卡', '代拿快递券', '晨跑免签卡', '定制志愿者T恤', '校徽纪念章', '不锈钢保温杯', '帆布手提袋', '爱奇艺月卡'),
            CONCAT('https://loremflickr.com/300/300/gift?lock=', p_i),
            FLOOR(50 + RAND()*500),
            FLOOR(10 + RAND()*100),
            IF(RAND() > 0.5, 1, 2), -- 1虚拟 2实物
            '志愿者专属福利，兑换后请到个人中心查看或线下领取。'
        );
        SET p_i = p_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 5. 生成 50 门培训课程 (题库关联)
    -- ---------------------------------------------------
    WHILE c_i < 50 DO
        VALUES (
            ELT(FLOOR(1+RAND()*5), '志愿者通用礼仪', '心肺复苏CPR急救', '大型赛会服务规范', '特殊群体沟通技巧', '活动策划与执行'),
            CONCAT('https://loremflickr.com/400/300/education?lock=', c_i),
            ELT(FLOOR(1+RAND()*4), '通识类', '技能类', '安全类', '领导力'),
            '本课程详细讲解了相关知识，通过学习您将掌握核心技能。',
            20
        );
        
        -- 为每门课生成题目
        
        SET c_i = c_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 6. 生成 300 条心得广场数据 (真实感)
    -- ---------------------------------------------------
    WHILE e_i < 300 DO
        VALUES (
            (SELECT id FROM volunteer ORDER BY RAND() LIMIT 1),
            (SELECT id FROM activity ORDER BY RAND() LIMIT 1),
            ELT(FLOOR(1+RAND()*5), '第一次参加志愿活动的感想', '累但快乐着！', '帮助别人真的很有意义', '记一次难忘的社区服务', '关于环保活动的一些思考'),
            '今天参加了这个活动，感触很深。虽然天气很热，但是看到大家的笑容，我觉得一切都值得了。特别是当我们完成任务的时候，那种成就感是无法言喻的。希望下次还能参加！',
            IF(RAND()>0.5, CONCAT('https://loremflickr.com/800/600/volunteer?lock=', e_i), NULL),
            1, -- 已发布
            FLOOR(RAND()*100), -- 点赞
            FLOOR(100+RAND()*1000), -- 浏览
            DATE_ADD(NOW(), INTERVAL -FLOOR(RAND()*30) DAY)
        );
        SET e_i = e_i + 1;
    END WHILE;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for mock_data_v14
-- ----------------------------
DROP PROCEDURE IF EXISTS `mock_data_v14`;
delimiter ;;
CREATE PROCEDURE `mock_data_v14`()
BEGIN
    DECLARE v_i INT DEFAULT 0;
    DECLARE o_i INT DEFAULT 0;
    DECLARE a_i INT DEFAULT 0;
    DECLARE p_i INT DEFAULT 0; 
    DECLARE c_i INT DEFAULT 0; 
    DECLARE e_i INT DEFAULT 0; 
    
    DECLARE user_id BIGINT;
    DECLARE default_pass VARCHAR(255) DEFAULT '$2a$10$N.zmdr9k7uOCQb376NoUnuTJ8iAt6Z5EHsM8lE9lBOsl7iKTVKIUi';
    
    -- 姓名库
    DECLARE surname VARCHAR(10);
    DECLARE givenname VARCHAR(10);
    DECLARE full_name VARCHAR(20);
    
    -- 活动变量
    DECLARE current_cat_id INT;
    DECLARE target_org_name VARCHAR(50);
    DECLARE final_org_id BIGINT; -- 修复核心：直接存 ID
    DECLARE v_keyword VARCHAR(50);
    DECLARE base_title VARCHAR(100);
    
    -- ---------------------------------------------------
    -- 1. 生成 12 个组织 (挂载到学院)
    -- ---------------------------------------------------
    WHILE o_i < 12 DO
        SET full_name = CASE o_i
            WHEN 0 THEN '计算机学院团委' WHEN 1 THEN '外国语学院青协' WHEN 2 THEN '经济管理学院'
            WHEN 3 THEN '土木工程学院' WHEN 4 THEN '艺术设计学院' WHEN 5 THEN '机械工程学院'
            WHEN 6 THEN '校青年志愿者协会' WHEN 7 THEN '校红十字会' WHEN 8 THEN '图书馆管理委员会'
            WHEN 9 THEN '后勤保障部' WHEN 10 THEN '法学院志愿队' ELSE '体育部'
        END;
        
        VALUES (CONCAT('ORG', LPAD(o_i, 3, '0')), default_pass, 'ORGANIZER', 1, CONCAT('https://api.dicebear.com/7.x/identicon/svg?seed=org_', o_i), full_name, '010-88661234');
        
        SET o_i = o_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 2. 生成 270 个志愿者 (真实姓名)
    -- ---------------------------------------------------
    SET v_i = 0;
    WHILE v_i < 270 DO
        SET surname = ELT(FLOOR(1+RAND()*20), '赵','钱','孙','李','周','吴','郑','王','冯','陈','褚','卫','蒋','沈','韩','杨','朱','秦','尤','许');
        SET givenname = ELT(FLOOR(1+RAND()*20), '伟','芳','娜','敏','静','强','磊','洋','艳','杰','娟','涛','明','超','秀','刚','平','燕','辉','玲');
        SET full_name = CONCAT(surname, givenname);
        
        VALUES (CAST((2024001001 + v_i) AS CHAR), default_pass, 'VOLUNTEER', 1, CONCAT('https://api.dicebear.com/7.x/notionists/svg?seed=stu_', v_i), full_name, CONCAT('138', LPAD(FLOOR(RAND()*100000000), 8, '0')));
        
        VALUES (LAST_INSERT_ID(), full_name, (v_i % 2 + 1), CAST((2024001001 + v_i) AS CHAR), 
            ELT(FLOOR(1+RAND()*6), '计算机学院','外国语学院','经管学院','土木学院','艺术学院','机械学院'), 
            '模拟专业', '2401班', FLOOR(RAND()*100), FLOOR(RAND()*500));
        SET v_i = v_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 3. 生成 300 个真实活动 (修复 NULL 错误)
    -- ---------------------------------------------------
    WHILE a_i < 300 DO
        SET current_cat_id = (a_i % 7) + 1;
        
        -- 定义分类对应的活动标题和目标组织名称（模糊匹配）
        CASE current_cat_id
            WHEN 1 THEN -- 社区服务
                SET v_keyword = 'community';
                SET base_title = ELT(FLOOR(1+RAND()*8), '老旧小区楼道清理', '社区垃圾分类指导', '居民法律知识宣讲', '流浪动物安置协助', '社区交通文明劝导', '防诈骗扫楼宣传', '社区健身器材维护', '爱心义剪进社区');
                SET target_org_name = '计算机'; -- 匹配计算机学院
            WHEN 2 THEN -- 环境保护
                SET v_keyword = 'nature';
                SET base_title = ELT(FLOOR(1+RAND()*6), '校园人工湖水质监测', '公园外来物种清理', '“限塑令”宣传行动', '废旧电池回收计划', '河流沿岸垃圾捡拾', '植树节绿化养护');
                SET target_org_name = '青协';
            WHEN 3 THEN -- 支教助学
                SET v_keyword = 'teaching';
                SET base_title = ELT(FLOOR(1+RAND()*6), '阳光小学课后辅导', '乡村英语启蒙夏令营', '特殊教育学校陪伴', '流动儿童融入计划', '爱心图书室整理', '趣味科学实验进小学');
                SET target_org_name = '外国语';
            WHEN 4 THEN -- 科技服务
                SET v_keyword = 'computer';
                SET base_title = ELT(FLOOR(1+RAND()*6), '电脑义务维修诊所', '老年人智能手机培训', '校园网络故障排查', '3D打印科普体验', '无人机飞行演示', '办公软件Office培训');
                SET target_org_name = '机械';
            WHEN 5 THEN -- 赛会服务
                SET v_keyword = 'sports';
                SET base_title = ELT(FLOOR(1+RAND()*6), '城市马拉松物资补给', '篮球联赛现场引导', '校运动会裁判助理', '游泳馆救生员助理', '电子竞技大赛统筹', '残运会无障碍协助');
                SET target_org_name = '体育';
            WHEN 6 THEN -- 敬老关怀
                SET v_keyword = 'elderly';
                SET base_title = ELT(FLOOR(1+RAND()*6), '敬老院包饺子活动', '独居老人陪聊计划', '老年人免费体检引导', '为老人读报教微信', '阿尔茨海默症关爱', '重阳节文艺汇演');
                SET target_org_name = '红十字';
            ELSE -- 文化艺术
                SET v_keyword = 'art';
                SET base_title = ELT(FLOOR(1+RAND()*6), '图书馆新书上架', '校史馆讲解员招募', '校园井盖涂鸦美化', '非遗剪纸体验助教', '博物馆周末引导员', '迎新晚会舞台搭建');
                SET target_org_name = '艺术';
        END CASE;
        
        -- 【核心修复】直接查找 organizer 表的 ID，而不是 user_id
        -- 并且增加保险丝：如果查不到，随机选一个存在的 ID
        SET final_org_id = NULL;
        SELECT id INTO final_org_id FROM organizer WHERE org_name LIKE CONCAT('%', target_org_name, '%') LIMIT 1;
        
        IF final_org_id IS NULL THEN
            SELECT id INTO final_org_id FROM organizer ORDER BY RAND() LIMIT 1;
        END IF;

            `title`, `category_id`, `organizer_id`, `cover_image`, `content`, `location`, 
            `start_time`, `end_time`, `deadline`, 
            `max_participants`, `current_participants`, `status`, `audit_status`, `service_hours`, `points`
        ) VALUES (
            CONCAT(base_title, ' (第', FLOOR(a_i/10)+1, '期)'), 
            current_cat_id, 
            final_org_id, -- 这里现在绝对不为空
            CONCAT('https://loremflickr.com/800/450/', v_keyword, '?lock=', a_i), 
            CONCAT('<p><b>活动背景：</b>', base_title, '旨在服务同学，回馈社会。</p><p><b>岗位职责：</b><br>1. 协助现场布置；<br>2. 维持秩序；<br>3. 提供咨询服务。</p><p><b>福利保障：</b><br>1. 志愿时长录入；<br>2. 综测加分；<br>3. 提供饮用水和午餐。</p>'), 
            ELT(FLOOR(1+RAND()*4), '第一教学楼', '学生活动中心', '校外社区', '图书馆广场'),
            DATE_ADD(NOW(), INTERVAL FLOOR(RAND()*60)-30 DAY),
            DATE_ADD(NOW(), INTERVAL FLOOR(RAND()*60)-29 DAY),
            DATE_ADD(NOW(), INTERVAL FLOOR(RAND()*60)-31 DAY),
            50, FLOOR(RAND()*50), FLOOR(2+RAND()*3), 1, FLOOR(2+RAND()*4), FLOOR(5+RAND()*15)
        );
        SET a_i = a_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 4. 生成 200 个商城商品
    -- ---------------------------------------------------
    WHILE p_i < 200 DO
        VALUES (
            ELT(FLOOR(1+RAND()*10), '活动免审核卡', '双倍积分卡', '补签卡', '代拿快递券', '晨跑免签卡', '定制志愿者T恤', '校徽纪念章', '不锈钢保温杯', '帆布手提袋', '爱奇艺月卡'),
            CONCAT('https://loremflickr.com/300/300/gift?lock=', p_i),
            FLOOR(50 + RAND()*500),
            FLOOR(10 + RAND()*100),
            IF(RAND() > 0.5, 1, 2), -- 1虚拟 2实物
            '志愿者专属福利，兑换后请到个人中心查看或线下领取。'
        );
        SET p_i = p_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 5. 生成 50 门培训课程
    -- ---------------------------------------------------
    WHILE c_i < 50 DO
        VALUES (
            ELT(FLOOR(1+RAND()*5), '志愿者通用礼仪', '心肺复苏CPR急救', '大型赛会服务规范', '特殊群体沟通技巧', '活动策划与执行'),
            CONCAT('https://loremflickr.com/400/300/education?lock=', c_i),
            ELT(FLOOR(1+RAND()*4), '通识类', '技能类', '安全类', '领导力'),
            '本课程详细讲解了相关知识，通过学习您将掌握核心技能。',
            20
        );
        
        -- 为每门课生成题目
        
        SET c_i = c_i + 1;
    END WHILE;

    -- ---------------------------------------------------
    -- 6. 生成 300 条心得广场数据
    -- ---------------------------------------------------
    WHILE e_i < 300 DO
        VALUES (
            (SELECT id FROM volunteer ORDER BY RAND() LIMIT 1),
            (SELECT id FROM activity ORDER BY RAND() LIMIT 1),
            ELT(FLOOR(1+RAND()*5), '第一次参加志愿活动的感想', '累但快乐着！', '帮助别人真的很有意义', '记一次难忘的社区服务', '关于环保活动的一些思考'),
            '今天参加了这个活动，感触很深。虽然天气很热，但是看到大家的笑容，我觉得一切都值得了。特别是当我们完成任务的时候，那种成就感是无法言喻的。希望下次还能参加！',
            IF(RAND()>0.5, CONCAT('https://loremflickr.com/800/600/volunteer?lock=', e_i), NULL),
            1, -- 已发布
            FLOOR(RAND()*100), 
            FLOOR(100+RAND()*1000), 
            DATE_ADD(NOW(), INTERVAL -FLOOR(RAND()*30) DAY)
        );
        SET e_i = e_i + 1;
    END WHILE;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for mock_data_v21_logic
-- ----------------------------
DROP PROCEDURE IF EXISTS `mock_data_v21_logic`;
delimiter ;;
CREATE PROCEDURE `mock_data_v21_logic`()
BEGIN
    -- 循环变量
    DECLARE i INT DEFAULT 0;
    
    -- 商品变量
    DECLARE p_name VARCHAR(100);
    DECLARE p_type INT; 
    DECLARE p_desc VARCHAR(255);
    DECLARE p_prefix VARCHAR(20);
    DECLARE p_suffix VARCHAR(20);
    DECLARE group_idx INT;
    DECLARE sub_idx INT;
    DECLARE item_idx INT;
    
    -- 课程变量
    DECLARE c_title VARCHAR(100);
    DECLARE c_cat VARCHAR(50);
    DECLARE c_content TEXT;
    DECLARE c_level VARCHAR(20);
    DECLARE c_topic VARCHAR(50);
    
    -- 流水变量
    DECLARE r_i INT DEFAULT 0;
    DECLARE r_user_id BIGINT;
    DECLARE r_item_id BIGINT;
    DECLARE r_course_id BIGINT;
    DECLARE r_points INT;
    DECLARE r_name VARCHAR(100);

    -- =======================================================
    -- A. 生成 200 个商品 (带 price 积分价格)
    -- =======================================================
    SET i = 0;
    WHILE i < 200 DO
        SET group_idx = FLOOR(i / 40);       
        SET sub_idx = FLOOR((i % 40) / 10);  
        SET item_idx = i % 10;               
        
        -- 分组逻辑同前，确保名字不重复
        IF group_idx = 0 THEN
            SET p_type = 2; SET p_prefix = ELT(sub_idx + 1, '晨光按动', '得力高透', '无印风', '志愿者定制');
            SET p_suffix = ELT(item_idx + 1, '中性笔黑(10支)', 'A5软皮笔记本', '加厚文件夹', '桌面订书机', '金属美工刀', '大号长尾夹', '荧光标记笔', '静音计算器', '磨砂笔筒', '便利贴套装');
        ELSEIF group_idx = 1 THEN
            SET p_type = 2; SET p_prefix = ELT(sub_idx + 1, '小米同款', '绿联认证', '倍思快充', '罗技代工');
            SET p_suffix = ELT(item_idx + 1, 'Type-C数据线', '无线静音鼠标', '手机桌面支架', '三合一充电线', '大号鼠标垫', 'USB扩展坞', '屏幕清洁剂', '蓝牙耳机套', '理线魔术贴', '迷你小风扇');
        ELSEIF group_idx = 2 THEN
            SET p_type = 2; SET p_prefix = ELT(sub_idx + 1, '维达', '蓝月亮', '洁柔', '舒肤佳');
            SET p_suffix = ELT(item_idx + 1, '抽纸(3包)', '洗衣液袋装', '抑菌洗手液', '纯棉洗脸巾', '纳米海绵擦', '活性炭除味包', '衣物收纳袋', '便携雨伞', '帆布手提袋', '不锈钢保温杯');
        ELSEIF group_idx = 3 THEN
            SET p_type = 1; SET p_prefix = ELT(sub_idx + 1, '月卡', '周卡', '日卡', '体验券');
            SET p_suffix = ELT(item_idx + 1, '爱奇艺会员', '网易云黑胶', '腾讯视频VIP', '饿了么红包', '美团外卖券', '哈啰单车卡', '百度网盘SVIP', '肯德基代金券', '瑞幸咖啡券', '打印店抵扣券');
        ELSE 
            SET p_type = 1; SET p_prefix = ELT(sub_idx + 1, '通用', '限定', '新手', '高级');
            SET p_suffix = ELT(item_idx + 1, '活动免审核卡', '迟到免责卡', '双倍积分卡', '补签卡(3天)', '优先报名权', '代拿快递券', '晨跑免打卡', '综测加分证明', '荣誉电子证书', '头像框装饰');
        END IF;

        SET p_name = CONCAT(p_prefix, '-', p_suffix);

        VALUES (
            p_name,
            CONCAT('https://loremflickr.com/300/300/product?lock=', i),
            FLOOR(100 + RAND() * 900), -- [重点] 积分价格 100-1000 (用于扣除)
            FLOOR(10 + RAND() * 100),
            p_type,
            '使用积分兑换此物品，库存有限，先到先得。'
        );
        SET i = i + 1;
    END WHILE;

    -- =======================================================
    -- B. 生成 200 节课程 (带 points_reward 积分奖励)
    -- =======================================================
    SET i = 0;
    WHILE i < 200 DO
        SET group_idx = FLOOR(i / 40);       
        SET sub_idx = FLOOR((i % 40) / 10);  
        SET item_idx = i % 10;               
        SET c_level = ELT(sub_idx + 1, '入门篇', '进阶篇', '高级篇', '专家篇');
        
        IF group_idx = 0 THEN
            SET c_cat = '通识培训'; SET c_topic = ELT(item_idx + 1, '志愿精神解读', '服务礼仪规范', '团队沟通技巧', '时间管理法则', '情绪压力管理', '安全法律常识', '常见突发应对', '活动策划基础', '新闻稿写作', '摄影拍摄技巧');
        ELSEIF group_idx = 1 THEN
            SET c_cat = '急救知识'; SET c_topic = ELT(item_idx + 1, '心肺复苏CPR', '海姆立克法', 'AED使用教学', '创伤包扎术', '骨折固定法', '火灾逃生演练', '防溺水知识', '中暑急救处理', '地震避险指南', '食物中毒应对');
        ELSEIF group_idx = 2 THEN
            SET c_cat = '支教技能'; SET c_topic = ELT(item_idx + 1, '儿童心理学', '课堂管理技巧', '趣味教学法', '教案编写指南', '家访沟通技巧', '特殊儿童关爱', '团队破冰游戏', '手工课程设计', '科普实验演示', '励志演讲技巧');
        ELSEIF group_idx = 3 THEN
            SET c_cat = '赛会服务'; SET c_topic = ELT(item_idx + 1, '大型赛事概论', '观众引导手势', '检票安检流程', 'VIP接待礼仪', '英语口语速成', '场馆动线熟悉', '物资管理分发', '突发纠纷调解', '无线电对讲机', '媒体接待规范');
        ELSE 
            SET c_cat = '专项技能'; SET c_topic = ELT(item_idx + 1, '垃圾分类标准', '水质监测入门', '动植物识别', '社区调研方法', '老年人护理', '手语基础教学', '盲文基础认知', '轮椅使用方法', '非遗文化传承', '法律援助基础');
        END IF;

        SET c_title = CONCAT('【', c_cat, '】', c_topic, '-', c_level);
        
        VALUES (
            c_title,
            CONCAT('https://loremflickr.com/400/225/learning?lock=', i),
            c_cat,
            CONCAT('<p>完成本课程学习并通过考试，即可获得积分奖励。</p><p>主题：', c_topic, '</p>'),
            IF(RAND()>0.5, 'https://media.w3.org/2010/05/sintel/trailer.mp4', NULL),
            FLOOR(10 + RAND() * 40) -- [重点] 积分奖励 10-50 (用于增加)
        );
        
        -- 生成题目

        SET i = i + 1;
    END WHILE;

    -- =======================================================
    -- C. [新增] 生成 1000 条积分流水 (模拟真实的 扣除/增加)
    -- =======================================================
    SET r_i = 0;
    WHILE r_i < 1000 DO
        -- 随机找一个志愿者
        SET r_user_id = (SELECT id FROM volunteer ORDER BY RAND() LIMIT 1);
        
        -- 50% 概率是买东西 (扣分)，50% 概率是上课 (加分)
        IF RAND() > 0.5 THEN
            -- [模拟购买] -> 扣除积分
            SELECT id, price, name INTO r_item_id, r_points, r_name FROM points_product ORDER BY RAND() LIMIT 1;
            
            VALUES (
                r_user_id, 
                -r_points, -- 负数，表示扣除
                FLOOR(100 + RAND() * 1000), -- 模拟余额
                2, -- 类型：消费
                CONCAT('兑换商品：', r_name),
                DATE_ADD(NOW(), INTERVAL -FLOOR(RAND()*60) DAY)
            );
        ELSE
            -- [模拟完课] -> 增加积分
            SELECT id, points_reward, title INTO r_course_id, r_points, r_name FROM train_course ORDER BY RAND() LIMIT 1;
            
            VALUES (
                r_user_id, 
                r_points, -- 正数，表示增加
                FLOOR(100 + RAND() * 1000), -- 模拟余额
                1, -- 类型：获取
                CONCAT('完成课程：', r_name),
                DATE_ADD(NOW(), INTERVAL -FLOOR(RAND()*60) DAY)
            );
        END IF;
        
        SET r_i = r_i + 1;
    END WHILE;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for mock_data_v23_exp
-- ----------------------------
DROP PROCEDURE IF EXISTS `mock_data_v23_exp`;
delimiter ;;
CREATE PROCEDURE `mock_data_v23_exp`()
BEGIN
    DECLARE e_i INT DEFAULT 0;
    
    WHILE e_i < 300 DO
        VALUES (
            (SELECT id FROM volunteer ORDER BY RAND() LIMIT 1),
            -- 50% 概率关联活动，50% 概率不关联 (模拟真实情况)
            IF(RAND()>0.5, (SELECT id FROM activity ORDER BY RAND() LIMIT 1), NULL),
            ELT(FLOOR(1+RAND()*5), '志愿者感想', '开心的一天', '帮助他人', '难忘经历', '环保随笔'),
            '今天参加志愿活动非常有意义...',
            NULL,
            1, FLOOR(RAND()*100), FLOOR(100+RAND()*1000), DATE_ADD(NOW(), INTERVAL -FLOOR(RAND()*30) DAY)
        );
        SET e_i = e_i + 1;
    END WHILE;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
